{"frozen_reasoning_spans":[{"end":97,"id":"S001","sha256":"8aaab624b875a6ed17c2f6418f64e19e0ce4cab25effd0d2952372cc3424c830","start":0,"text":"The equation |x| = 2x + 18 can be split into two cases based on the definition of absolute value."},{"end":163,"id":"S002","sha256":"b15d00b403be00b35e591577e8988bb843ec6dbf84b0fccebb8025f71bd468dc","start":98,"text":"Case 1: x \u2265 0, then |x| = x, so the equation becomes x = 2x + 18."},{"end":225,"id":"S003","sha256":"9a0571da062ebd6625532dfa91c1cee0a95f1f1ace860e3618685b9a8d8497e5","start":164,"text":"Solving for x gives x = -18, but this does not satisfy x \u2265 0."},{"end":293,"id":"S004","sha256":"5443b5429a37cc1241434bf59bec5afe2b7c47c75223944be81857e3af2720e0","start":226,"text":"Case 2: x < 0, then |x| = -x, so the equation becomes -x = 2x + 18."},{"end":321,"id":"S005","sha256":"9667754c14ec4b0086007303a8060c939ebd5bf564a650219a02787b6490c661","start":294,"text":"Solving for x gives x = -6."},{"end":377,"id":"S006","sha256":"6dde7760cbbbc703567af95f579fdb7315e82556d971d71f98778bf79df4aa51","start":322,"text":"Since -6 < 0, it satisfies the condition for this case."},{"end":412,"id":"S007","sha256":"1c400d4c11cf8aab5124847ffe1df9a7235567a3a4a71ece468ac7151bb2449b","start":378,"text":"Therefore, the solution is x = -6."}],"problem":"Solve for x: |x| = 2x + 18. Report the value of x.","problem_id":"cw1-bc3cca7bcfbf","span_projection_version":"action-census-reasoning-span-projection-v1"}

